package com.example.data

object CatechismPart2 {
    fun getArticles(): List<CatechismArticle> {
        val list = mutableListOf<CatechismArticle>()

        // -------------------------------------------------------------------
        // SECTION 2: HOPE, PRAYER, CHARITY & COMMANDMENTS 1-4 (Q91 - Q180)
        // -------------------------------------------------------------------

        // Q91 - Q100: Virtue of Hope & Necessity of Prayer
        list.add(CatechismArticle("cat_091", "Hope & Prayer", "Q. 91", "What is Hope?", "What is Hope?", "Hope is a supernatural theological virtue by which we firmly expect that God will grant us eternal life and the graces necessary to obtain it, through the merits of Jesus Christ.", "Council of Trent, Sess. 6; Penny Catechism Q.91", "hope, virtue, grace, eternal life, trust"))
        list.add(CatechismArticle("cat_092", "Hope & Prayer", "Q. 92", "On what is our Hope grounded?", "On what is our Hope grounded?", "Our Hope is grounded on the infinite goodness, power, and mercy of God, and on His faithful promises.", "Penny Catechism Q.92; Hebrews 10:23", "grounded, mercy, power, promise, trust"))
        list.add(CatechismArticle("cat_093", "Hope & Prayer", "Q. 93", "Can we do any good work deserving of Heaven without God's help?", "Can we do any good work deserving of Heaven without God's help?", "No, without God's actual grace we can do no supernatural good work deserving of Heaven: 'Without Me you can do nothing' (John 15:5).", "Council of Trent, Sess. 6; John 15:5; Penny Catechism Q.93", "grace, supernatural merit, good works, help of god"))
        list.add(CatechismArticle("cat_094", "Hope & Prayer", "Q. 94", "How do we obtain God's grace and help?", "How do we obtain God's grace and help?", "We obtain God's grace and help chiefly by Prayer and the Holy Sacraments.", "Penny Catechism Q.94; Catechism of Trent", "prayer, sacraments, grace, help"))
        list.add(CatechismArticle("cat_095", "Hope & Prayer", "Q. 95", "What is Prayer?", "What is Prayer?", "Prayer is the raising up of our mind and heart to God, to praise Him, thank Him, ask His forgiveness, and petition Him for all our spiritual and temporal needs.", "St. John Damascene; St. Alphonsus Liguori; Penny Catechism Q.95", "prayer, definition, mind and heart, praise, petition"))
        list.add(CatechismArticle("cat_096", "Hope & Prayer", "Q. 96", "Is prayer necessary for salvation?", "Is prayer necessary for salvation?", "Yes, prayer is absolutely necessary for the salvation of all who have reached the use of reason. St. Alphonsus teaches: 'He who prays is saved; he who prays not is damned.'", "St. Alphonsus Liguori; Luke 18:1; Matthew 7:7; Penny Catechism Q.96", "necessity of prayer, salvation, alphonsus, ask and receive"))
        list.add(CatechismArticle("cat_097", "Hope & Prayer", "Q. 97", "At what times ought we especially to pray?", "At what times ought we especially to pray?", "We ought to pray especially in the morning and evening, before and after meals, in times of temptation, and in all dangers of body and soul.", "Penny Catechism Q.97", "morning, evening, temptation, danger, meals"))
        list.add(CatechismArticle("cat_098", "Hope & Prayer", "Q. 98", "How should we pray to obtain our requests?", "How should we pray to obtain our requests?", "We should pray with attention, humility, confidence, perseverance, and in the Name of Jesus Christ.", "John 16:23; James 1:6; Penny Catechism Q.98", "attention, humility, confidence, perseverance, in jesus name"))
        list.add(CatechismArticle("cat_099", "Hope & Prayer", "Q. 99", "Which is the best of all prayers?", "Which is the best of all prayers?", "The Lord's Prayer (the 'Our Father') is the best of all prayers, because it was taught to us by Our Lord Jesus Christ Himself.", "Matthew 6:9-13; Luke 11:2-4; Penny Catechism Q.99", "lords prayer, our father, jesus, best prayer"))
        list.add(CatechismArticle("cat_100", "Hope & Prayer", "Q. 100", "Recite the Lord's Prayer", "Recite the Lord's Prayer", "Our Father, who art in heaven, hallowed be Thy name; Thy kingdom come; Thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen.", "Matthew 6:9-13", "our father, pater noster, text"))

        // Q101 - Q110: The Seven Petitions of the Lord's Prayer & The Hail Mary
        list.add(CatechismArticle("cat_101", "Hope & Prayer", "Q. 101", "Who is meant by 'Our Father'?", "Who is meant by 'Our Father'?", "By 'Our Father' is meant Almighty God, who is our Father by creation, and by adoption through grace.", "Penny Catechism Q.101; Romans 8:15", "our father, adoption, creator, grace"))
        list.add(CatechismArticle("cat_102", "Hope & Prayer", "Q. 102", "Why do we say 'hallowed be Thy name'?", "Why do we say 'hallowed be Thy name'?", "We say 'hallowed be Thy name' to ask that God's holy Name may be known, honored, and glorified throughout the whole world.", "Penny Catechism Q.102", "hallowed, holy name, glory, praise"))
        list.add(CatechismArticle("cat_103", "Hope & Prayer", "Q. 103", "Why do we say 'Thy kingdom come'?", "Why do we say 'Thy kingdom come'?", "We ask that God may reign in our souls by His grace in this life, and grant us His heavenly kingdom in the next.", "Penny Catechism Q.103", "kingdom come, grace, reign, heaven"))
        list.add(CatechismArticle("cat_104", "Hope & Prayer", "Q. 104", "Why do we say 'Thy will be done on earth as it is in heaven'?", "Why do we say 'Thy will be done on earth as it is in heaven'?", "We ask that we may obey God's holy commandments on earth as perfectly as the Angels and Saints obey Him in Heaven.", "Penny Catechism Q.104", "thy will be done, obedience, commandments, saints"))
        list.add(CatechismArticle("cat_105", "Hope & Prayer", "Q. 105", "What do we ask for in 'Give us this day our daily bread'?", "What do we ask for in 'Give us this day our daily bread'?", "We ask for all things necessary for our bodily sustenance, and especially for spiritual nourishment—the Holy Eucharist and God's grace.", "Penny Catechism Q.105; Catechism of Trent", "daily bread, sustenance, eucharist, grace"))
        list.add(CatechismArticle("cat_106", "Hope & Prayer", "Q. 106", "What do we ask in 'Forgive us our trespasses, as we forgive those who trespass against us'?", "What do we ask in 'Forgive us our trespasses, as we forgive those who trespass against us'?", "We ask God to forgive us our sins, as we sincerely forgive all who have offended or injured us.", "Matthew 6:14-15; Penny Catechism Q.106", "forgiveness, trespasses, mercy, pardon"))
        list.add(CatechismArticle("cat_107", "Hope & Prayer", "Q. 107", "What do we ask in 'Lead us not into temptation'?", "What do we ask in 'Lead us not into temptation'?", "We ask God to protect us from being overcome by the temptations of the devil, the world, and the flesh.", "1 Corinthians 10:13; Penny Catechism Q.107", "temptation, devil, world, flesh, protection"))
        list.add(CatechismArticle("cat_108", "Hope & Prayer", "Q. 108", "What do we ask in 'Deliver us from evil'?", "What do we ask in 'Deliver us from evil'?", "We ask God to deliver us from all evil of body and soul, both in time and in eternity, and especially from mortal sin and eternal damnation.", "Penny Catechism Q.108", "deliver us, evil, mortal sin, damnation"))
        list.add(CatechismArticle("cat_109", "Hope & Prayer", "Q. 109", "Which prayer do we use next to the Lord's Prayer?", "Which prayer do we use next to the Lord's Prayer?", "Next to the Lord's Prayer, we use the Hail Mary (the Angelic Salutation).", "Penny Catechism Q.109", "hail mary, angelic salutation, marian prayer"))
        list.add(CatechismArticle("cat_110", "Hope & Prayer", "Q. 110", "Recite the Hail Mary", "Recite the Hail Mary", "Hail Mary, full of grace, the Lord is with thee; blessed art thou amongst women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.", "Luke 1:28, 42; Council of Ephesus (431)", "hail mary, ave maria, text"))

        // Q111 - Q120: Marian Intercession & The Virtue of Charity
        list.add(CatechismArticle("cat_111", "Hope & Prayer", "Q. 111", "Who composed the Hail Mary?", "Who composed the Hail Mary?", "The first part was spoken by the Archangel Gabriel and St. Elizabeth; the second part was added by the Holy Catholic Church.", "Luke 1:28, 42; Catechism of Trent; Penny Catechism Q.111", "gabriel, elizabeth, church, angelic salutation"))
        list.add(CatechismArticle("cat_112", "Hope & Prayer", "Q. 112", "Why do we ask the Blessed Virgin Mary to pray for us?", "Why do we ask the Blessed Virgin Mary to pray for us?", "Because Mary is the Mother of God, the Queen of Heaven, and our powerful Advocate whose intercession before her Divine Son is never refused.", "Pope Leo XIII; St. Alphonsus, Glories of Mary; Penny Catechism Q.112", "mary, mother of god, advocate, intercession"))
        list.add(CatechismArticle("cat_113", "Hope & Prayer", "Q. 113", "Should we also invoke the Angels and Saints?", "Should we also invoke the Angels and Saints?", "Yes, we should invoke the Angels and Saints, asking them to intercede for us before God in Heaven.", "Council of Trent, Sess. 25 (1563); Penny Catechism Q.113", "angels, saints, intercession, invocation"))
        list.add(CatechismArticle("cat_114", "Hope & Prayer", "Q. 114", "Do we worship the Saints or Blessed Mary as God?", "Do we worship the Saints or Blessed Mary as God?", "No! We offer divine worship (latria) to God alone. We honor the Saints with veneration (dulia) and Mary with hyperdulia, as God's faithful servants and friends.", "Council of Trent, Sess. 25; St. Thomas Aquinas, ST II-II q.103", "latria, dulia, hyperdulia, worship, veneration, saints"))
        list.add(CatechismArticle("cat_115", "Hope & Prayer", "Q. 115", "What is Charity?", "What is Charity?", "Charity is a supernatural theological virtue by which we love God above all things for His own sake, and our neighbor as ourselves for the love of God.", "Penny Catechism Q.115; 1 Corinthians 13:13", "charity, love of god, love of neighbor, virtue"))
        list.add(CatechismArticle("cat_116", "Hope & Prayer", "Q. 116", "Why must we love God above all things?", "Why must we love God above all things?", "Because God is infinitely good, perfect, and deserving of all our love.", "Penny Catechism Q.116", "love god, infinite goodness, perfection"))
        list.add(CatechismArticle("cat_117", "Hope & Prayer", "Q. 117", "How do we show that we love God?", "How do we show that we love God?", "We show that we love God by keeping His holy commandments: 'If you love Me, keep My commandments' (John 14:15).", "John 14:15; 1 John 5:3; Penny Catechism Q.117", "commandments, love in action, obedience"))
        list.add(CatechismArticle("cat_118", "Hope & Prayer", "Q. 118", "Who is our neighbor whom we must love?", "Who is our neighbor whom we must love?", "Our neighbor is every human person without exception, even our enemies and persecutors.", "Matthew 5:44; Luke 10:29-37; Penny Catechism Q.118", "neighbor, love enemies, universal charity"))
        list.add(CatechismArticle("cat_119", "Hope & Prayer", "Q. 119", "Why must we love our neighbor?", "Why must we love our neighbor?", "Because all men are created in the image of God, redeemed by the Blood of Christ, and commanded by Christ to love one another.", "John 13:34; 1 John 4:21; Penny Catechism Q.119", "image of god, redemption, commandment of love"))
        list.add(CatechismArticle("cat_120", "Hope & Prayer", "Q. 120", "How many Commandments of God are there?", "How many Commandments of God are there?", "There are Ten Commandments of God, given to Moses on Mount Sinai.", "Exodus 20:1-17; Penny Catechism Q.120", "ten commandments, moses, sinai, law"))

        // Q121 - Q130: The Ten Commandments Recited & First Commandment (Worship & Faith)
        list.add(CatechismArticle("cat_121", "Charity & Commandments", "Q. 121", "Recite the Ten Commandments", "Recite the Ten Commandments", "1. I am the Lord thy God: thou shalt not have strange gods before Me.\n2. Thou shalt not take the name of the Lord thy God in vain.\n3. Remember that thou keep holy the Sabbath day.\n4. Honor thy father and thy mother.\n5. Thou shalt not kill.\n6. Thou shalt not commit adultery.\n7. Thou shalt not steal.\n8. Thou shalt not bear false witness against thy neighbor.\n9. Thou shalt not covet thy neighbor's wife.\n10. Thou shalt not covet thy neighbor's goods.", "Exodus 20:2-17; Deuteronomy 5:6-21", "ten commandments, decalogue, list"))
        list.add(CatechismArticle("cat_122", "Charity & Commandments", "Q. 122", "Who gave the Ten Commandments?", "Who gave the Ten Commandments?", "God Himself gave the Ten Commandments to Moses on Mount Sinai, and Jesus Christ confirmed them in the Gospel.", "Exodus 20:1; Matthew 19:17; Penny Catechism Q.122", "god, moses, Gospel, decalogue"))
        list.add(CatechismArticle("cat_123", "Charity & Commandments", "Q. 123", "What is the First Commandment?", "What is the First Commandment?", "The First Commandment is: 'I am the Lord thy God: thou shalt not have strange gods before Me.'", "Penny Catechism Q.123", "first commandment, strange gods, worship"))
        list.add(CatechismArticle("cat_124", "Charity & Commandments", "Q. 124", "What are we commanded to do by the First Commandment?", "What are we commanded to do by the First Commandment?", "We are commanded to worship the One True God alone, by faith, hope, charity, and religion.", "Penny Catechism Q.124", "worship, true god, faith, hope, charity"))
        list.add(CatechismArticle("cat_125", "Charity & Commandments", "Q. 125", "What does the First Commandment forbid?", "What does the First Commandment forbid?", "The First Commandment forbids idolatry, superstition, sacrilege, heresy, apostasy, schism, and all active participation in non-Catholic religious worship.", "Exodus 20:3; Canon 1258 (1917 Code); Penny Catechism Q.125", "idolatry, superstition, sacrilege, heresy, apostasy, schism, non-catholic worship"))
        list.add(CatechismArticle("cat_126", "Charity & Commandments", "Q. 126", "What is Heresy?", "What is Heresy?", "Heresy is the obstinate post-baptismal denial or doubt of any dogmatic truth which must be believed with divine and Catholic faith.", "Canon 1325 §2 (1917 Code); St. Thomas, ST II-II q.11", "heresy, denial, dogma, obstinacy"))
        list.add(CatechismArticle("cat_127", "Charity & Commandments", "Q. 127", "What is Apostasy?", "What is Apostasy?", "Apostasy is the total rejection and abandonment of the Christian and Catholic Faith by a baptized person.", "Canon 1325 §2 (1917 Code); Heb 10:26-29", "apostasy, total rejection, faith, abandonment"))
        list.add(CatechismArticle("cat_128", "Charity & Commandments", "Q. 128", "What is Schism?", "What is Schism?", "Schism is the refusal to submit to the supreme authority of the Roman Pontiff or to hold communion with the members of the Church subject to him.", "Canon 1325 §2 (1917 Code); St. Cyprian", "schism, rebellion, pope, communion"))
        list.add(CatechismArticle("cat_129", "Charity & Commandments", "Q. 129", "Does the First Commandment forbid honoring images or statues?", "Does the First Commandment forbid honoring images or statues?", "No! It forbids giving divine worship to images or statues. But we honor holy statues and images of Christ, Mary, and the Saints because the honor paid to them passes to the prototype they represent.", "Council of Nicaea II (787); Council of Trent, Sess. 25", "images, statues, nicaea ii, veneration, prototype"))
        list.add(CatechismArticle("cat_130", "Charity & Commandments", "Q. 130", "Is it lawful to honor relics of Saints?", "Is it lawful to honor relics of Saints?", "Yes, it is good and lawful to honor the sacred relics of the Saints, because their bodies were temples of the Holy Ghost and will rise in glory.", "Council of Trent, Sess. 25 (1563); 2 Kings 13:21", "relics, saints, veneration, council of trent"))

        // Q131 - Q140: Second & Third Commandments (Holy Name & Holy Days)
        list.add(CatechismArticle("cat_131", "Charity & Commandments", "Q. 131", "What is the Second Commandment?", "What is the Second Commandment?", "The Second Commandment is: 'Thou shalt not take the name of the Lord thy God in vain.'", "Penny Catechism Q.131", "second commandment, name in vain, blasphemy"))
        list.add(CatechismArticle("cat_132", "Charity & Commandments", "Q. 132", "What does the Second Commandment command?", "What does the Second Commandment command?", "We are commanded to speak with reverence of God, of Jesus Christ, of His Holy Name, of the Blessed Virgin, and of holy things, and to keep lawful vows and oaths.", "Penny Catechism Q.132", "reverence, holy name, vows, oaths"))
        list.add(CatechismArticle("cat_133", "Charity & Commandments", "Q. 133", "What does the Second Commandment forbid?", "What does the Second Commandment forbid?", "It forbids all profaning of God's Name, blasphemy, false or rash oaths, cursing, and broken vows.", "Penny Catechism Q.133; Leviticus 19:12", "blasphemy, cursing, false oaths, swearing"))
        list.add(CatechismArticle("cat_134", "Charity & Commandments", "Q. 134", "What is Blasphemy?", "What is Blasphemy?", "Blasphemy is speaking contemptuous, insulting, or abusive words against God, His Blessed Mother, the Saints, or holy things.", "St. Thomas, ST II-II q.13; Penny Catechism Q.134", "blasphemy, insult, disrespect, god"))
        list.add(CatechismArticle("cat_135", "Charity & Commandments", "Q. 135", "What is the Third Commandment?", "What is the Third Commandment?", "The Third Commandment is: 'Remember that thou keep holy the Sabbath day.'", "Penny Catechism Q.135", "third commandment, sabbath, sunday"))
        list.add(CatechismArticle("cat_136", "Charity & Commandments", "Q. 136", "Why was the Sabbath changed from Saturday to Sunday?", "Why was the Sabbath changed from Saturday to Sunday?", "The Church changed the Sabbath to Sunday because Jesus Christ rose from the dead on Sunday, and the Holy Ghost descended on Pentecost Sunday.", "Catechism of Trent; Acts 20:7; 1 Corinthians 16:2", "sunday, lord's day, resurrection, change of sabbath"))
        list.add(CatechismArticle("cat_137", "Charity & Commandments", "Q. 137", "How are we commanded to keep Sunday holy?", "How are we commanded to keep Sunday holy?", "We are commanded to keep Sunday holy by assisting at the Holy Sacrifice of the Mass, and refraining from unnecessary servile work and commercial business.", "Canon 1247 (1917 Code); Penny Catechism Q.137", "sunday, mass, servile work, rest, holy day"))
        list.add(CatechismArticle("cat_138", "Charity & Commandments", "Q. 138", "What is servile work?", "What is servile work?", "Servile work is physical manual labor, such as plowing, building, or trade, which was formerly done by slaves.", "Penny Catechism Q.138", "servile work, manual labor, sunday rest"))
        list.add(CatechismArticle("cat_139", "Charity & Commandments", "Q. 139", "What servile work is allowed on Sunday?", "What servile work is allowed on Sunday?", "Work that is required for divine worship, works of charity, and work of immediate necessity (such as emergency medical care or cooking).", "Penny Catechism Q.139; Luke 14:5", "necessity, charity, sunday labor"))
        list.add(CatechismArticle("cat_140", "Charity & Commandments", "Q. 140", "Is missing Mass on Sunday a mortal sin?", "Is missing Mass on Sunday a mortal sin?", "Yes, deliberately missing Holy Mass on a Sunday or Holy Day of Obligation without a grave excusing reason (such as severe illness) is a mortal sin.", "1917 Code of Canon Law, Canon 1248; Penny Catechism Q.140", "missing mass, mortal sin, obligation, sunday"))

        // Q141 - Q150: Fourth Commandment (Parents, Authority & Duties)
        list.add(CatechismArticle("cat_141", "Charity & Commandments", "Q. 141", "What is the Fourth Commandment?", "What is the Fourth Commandment?", "The Fourth Commandment is: 'Honor thy father and thy mother.'", "Penny Catechism Q.141", "fourth commandment, parents, honor, obedience"))
        list.add(CatechismArticle("cat_142", "Charity & Commandments", "Q. 142", "What are children commanded to do toward their parents?", "What are children commanded to do toward their parents?", "Children are commanded to love, respect, obey, and assist their parents in all that is not sinful.", "Ephesians 6:1-3; Colossians 3:20; Penny Catechism Q.142", "children, parents, love, obedience, respect"))
        list.add(CatechismArticle("cat_143", "Charity & Commandments", "Q. 143", "What are the duties of parents toward their children?", "What are the duties of parents toward their children?", "Parents must love, provide for, educate, discipline, and bring up their children in the true Catholic Faith and fear of God.", "Ephesians 6:4; Penny Catechism Q.143", "parents duties, Catholic education, rearing children"))
        list.add(CatechismArticle("cat_144", "Charity & Commandments", "Q. 144", "Must we obey civil authority?", "Must we obey civil authority?", "Yes, we must obey lawful civil authority in all things that are not contrary to the law of God and the Holy Catholic Church: 'Render to Caesar the things that are Caesar's, and to God the things that are God's' (Mark 12:17).", "Romans 13:1-7; Mark 12:17; Penny Catechism Q.144", "civil authority, government, caesar, obedience"))
        list.add(CatechismArticle("cat_145", "Charity & Commandments", "Q. 145", "What if a civil law commands something sinful?", "What if a civil law commands something sinful?", "If any human or civil authority commands what is contrary to God's law, we must obey God rather than men: 'We ought to obey God rather than men' (Acts 5:29).", "Acts 5:29; Pope Leo XIII, Immortale Dei", "god over men, sinful laws, resistance, conscience"))
        list.add(CatechismArticle("cat_146", "Charity & Commandments", "Q. 146", "Are we obligated to respect ecclesiastical authority?", "Are we obligated to respect ecclesiastical authority?", "Yes, we must respect, obey, and support our lawful Catholic pastors and bishops in all spiritual matters.", "Hebrews 13:17; Penny Catechism Q.146", "pastors, bishops, spiritual obedience, hierarchy"))
        list.add(CatechismArticle("cat_147", "Charity & Commandments", "Q. 147", "What does the Fifth Commandment command?", "What does the Fifth Commandment command?", "The Fifth Commandment ('Thou shalt not kill') commands us to preserve our own life and the lives of others, and to live in peace and charity.", "Penny Catechism Q.147", "fifth commandment, preservation of life, peace"))
        list.add(CatechismArticle("cat_148", "Charity & Commandments", "Q. 148", "What does the Fifth Commandment forbid?", "What does the Fifth Commandment forbid?", "It forbids murder, suicide, abortion, euthanasia, dueling, anger, hatred, revenge, drunkenness, and scandal.", "Exodus 20:13; Catechism of Trent; Penny Catechism Q.148", "murder, abortion, suicide, euthanasia, anger, scandal"))
        list.add(CatechismArticle("cat_149", "Charity & Commandments", "Q. 149", "Is direct abortion always a mortal sin?", "Is direct abortion always a mortal sin?", "Yes! Direct abortion is the murder of an innocent unborn human child, a grave crime that cries out to Heaven for vengeance.", "Ex-Cathedra Papal Teaching; Didache (c. 90 AD); Canon 2350 (1917 Code)", "abortion, murder, unborn, grave crime, mortal sin"))
        list.add(CatechismArticle("cat_150", "Charity & Commandments", "Q. 150", "Is suicide a mortal sin?", "Is suicide a mortal sin?", "Yes, suicide is self-murder, a grave offense against God who alone is the Master of human life.", "Penny Catechism Q.150; St. Thomas Aquinas", "suicide, self murder, master of life"))

        return list
    }
}
